<template>
  <q-select
    outlined
    :model-value="modelValue"
    :options="filteredUsers"
    :label="$t('select_user')"
    dense
    emit-value
    map-options
    option-value="value"
    option-label="label"
    use-input
    hide-selected
    fill-input
    @update:model-value="(val: string) => $emit('update:modelValue', val)"
    @filter="filterFn"
  />
</template>

<script lang="ts">
import { defineComponent } from 'vue';
import stringMixin from 'src/utils/string';

export default defineComponent({
  name: 'UserSelect',
  mixins: [stringMixin],
  props: {
    modelValue: {
      type: [String, Number, null] as any,
      default: null,
    },
    users: {
      type: Array as () => Array<{ label: string; value: any }>,
      default: () => [],
    },
  },
  emits: ['update:modelValue'],
  data() {
    return {
      // Seed with the full list so emit-value/map-options can resolve the
      // selected value's label on first render, before @filter ever fires.
      filteredUsers: [...this.users] as Array<{ label: string; value: any }>,
    };
  },
  watch: {
    // The user list is fetched async after mount; keep options in sync so
    // saved values still resolve to labels once it arrives.
    users(newUsers: Array<{ label: string; value: any }>) {
      this.filteredUsers = [...newUsers];
    },
  },
  methods: {
    filterFn(val: string, update: any) {
      if (val === '') {
        update(() => {
          this.filteredUsers = this.users;
        });
        return;
      }

      update(() => {
        if (/^\d+$/.test(val)) {
          this.filteredUsers = this.users.filter(
            (option) => option.value === Number(val),
          );
        } else if (/^[a-zA-Z ]+$/.test(val)) {
          this.filteredUsers = this.users.filter((option) =>
            this.normalizeString(option.label).includes(
              this.normalizeString(val),
            ),
          );
        } else {
          this.filteredUsers = this.users;
        }
      });
    },
  },
});
</script>
