<script lang="ts">
// @ts-nocheck
import UserSelect from './UserSelect.vue';
import { defineComponent, ref } from 'vue';
import { Icon } from '@iconify/vue';
import helperUtil from 'src/utils/helperUtil';
import Loader from 'src/components/Loader.vue';
import { notify } from 'src/components/notifications/notify';
import { decisionApiService, userApiService } from 'src/services';
import helperMixin from 'src/mixins/helperMixin';
import displayFieldLabel from 'src/utils/displayFieldLabel';
import type { dynamicObj } from 'src/pages/assets';
import { isUndefinedOrNull } from 'src/utils/general';
import { ApiExceptions } from 'src/exceptions';
import stringMixin from 'src/utils/string';
import { TranslationKey } from '@tolgee/vue';
import { rules_options_filter } from 'src/constants';

export default defineComponent({
  name: 'decisionDesigner',
  mixins: [helperUtil, helperMixin, stringMixin, displayFieldLabel],
  components: { Loader, UserSelect, Icon },
  mounted() {
    this.initView();
    (<any>window).dt = this;

    // Set up scroll sync after DOM is ready
    this.$nextTick(() => {
      this.setupScrollSync();
    });
  },
  beforeUnmount() {
    // Clean up scroll sync flag
    this.isScrollSyncing = false;
    // Remove scroll listeners
    if (this.conditionScrollEl) {
      this.conditionScrollEl.removeEventListener(
        'scroll',
        this.onConditionScroll,
      );
    }
    if (this.resultScrollEl) {
      this.resultScrollEl.removeEventListener('scroll', this.onResultScroll);
    }
  },
  methods: {
    openTestDialog() {
      this.first_rule_fields = JSON.parse(
        JSON.stringify(this.rules[0].conditions),
      );
      this.testDialog = true;
    },

    highlightLines(lineIDs: []) {
      this.clearHighlight();
      for (let id of lineIDs) {
        for (let [rule_key, rule] of Object.entries(this.rules)) {
          if (rule.id == id) {
            this.highlightedLineID = id;
            if (!Array.isArray(this.highlightedLineIDs)) {
              this.highlightedLineIDs = [];
            }
            this.highlightedLineIDs.push(id);
          }
        }
      }
    },

    clearHighlight() {
      this.highlightedLineIDs = [];
    },

    async handleDone() {
      const decisionTreeId = this.$route.params.id as string;

      this.first_rule_fields.forEach((element: any) => {
        this.doc_fields.push({
          name: element.field_name,
          value: element.value,
        });
      });

      this.showLoading();
      const response = (await decisionApiService.testDecisionTree(
        JSON.stringify(this.doc_fields),
        decisionTreeId,
      )) as dynamicObj;

      this.initView();
      this.hideLoading();

      if (response.success == true) {
        logInfo(response);
        let lineIDs = [];
        if (response.ID != null && Array.isArray(response.ID)) {
          lineIDs = response.ID;
          this.highlightLines(lineIDs as []);

          this.testResultDialog = true;
          this.testResults = response;

          //Remove Row highlights after 15 seconds
          setTimeout(() => {
            this.highlightedLineIDs = [];
          }, 15000);
        } else {
          this.clearHighlight();
          notify.success(response.message);
        }
      } else {
        this.clearHighlight();
        notify.success(response.message);
      }

      this.doc_fields = [];
      this.testDialog = false;
    },

    async initView() {
      const decisionTreeId = this.$route.params.id as string;
      try {
        this.showLoading();
        const response = (await decisionApiService.getDecisionTree(
          decisionTreeId,
        )) as dynamicObj;
        if (response.hasOwnProperty('success') && response.success === false) {
          throw response;
        }

        this.record = response.data;
        this.completeDataSet = this.record.data;
        if (this.record.data != null) {
          this.record.data = this.record.data.slice(
            (this.currentPage - 1) * 100,
            this.currentPage * 100,
          );
        }
        this.decisionTreeName = this.record.name;
        this.splitter = 65;

        await this.getData();

        if (isUndefinedOrNull(this.record.data)) {
          this.initData();
          return;
        }
        this.prepareDataForView();
        this.removeConditionalOptions();
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.hideLoading();
      }
    },

    async getData() {
      try {
        this.doc_field_resp = await decisionApiService.getDocumentTypeFields(
          this.record.doc_type as string,
        );
        const users_resp = await userApiService.getUsers();
        const group_resp = await userApiService.getGroups();

        this.columnOptions = [];
        this.userOptions = [];
        this.groupOptions = [];
        this.field_type_mapping = {};

        this.columnOptions.push({
          label: this.$t('none'),
          value: 'None',
          type: '',
        });
        this.userOptions.push({
          label: this.$t('blank_user_or_group'),
          value: 'None',
        });
        this.groupOptions.push({
          label: this.$t('blank_user_or_group'),
          value: 'None',
        });

        this.doc_field_resp.forEach((element: any) => {
          this.columnOptions.push({
            label:
              this.formatFieldName(element.field_name) +
              ' - ' +
              element.field_type.charAt(0).toUpperCase() +
              element.field_type.slice(1).toLowerCase(),
            value: element.field_name,
            type: element.field_type,
          });
        });
        users_resp.forEach((element: any) => {
          this.userOptions.push({
            label: element.first_name + ' ' + element.last_name,
            value: element.id,
          });
        });
        this.columnOptionsDup = [...this.columnOptions];
        group_resp.forEach((element: any) => {
          this.groupOptions.push({ label: element.name, value: element.id });
        });
        this.groupOptionsDup = [...this.groupOptions];
      } catch (error) {
        notify.error(error);
      } finally {
        this.hideLoading();
      }
    },

    getFieldType(field_name: any) {
      const fieldIndex = this.columnOptions.findIndex(
        (element) => element.value === field_name,
      );

      if (!this.field_type_mapping.hasOwnProperty(field_name)) {
        this.field_type_mapping[field_name] =
          this.columnOptions[fieldIndex].type;
      }
    },

    // "Select Document Field" values live in fixed-width columns and are
    // frequently truncated (e.g. "Tax amount" vs "Tax amount reduced").
    // Resolve the full option label so a tooltip can show it on hover,
    // falling back to a formatted version of the raw value when the field
    // list hasn't loaded yet.
    getDocFieldTooltipLabel(field_value: string): string {
      if (!field_value) {
        return '';
      }
      const match = this.columnOptions.find(
        (option) => option.value === field_value,
      );
      return match ? match.label : this.formatFieldName(field_value);
    },

    async updateRecord() {
      if (!this.isValid) {
        notify.error('Invalid priority value\nPlease select a value 1-999');
        return;
      }

      if (!this.record.tree_rule) {
        notify.error(this.$t('decision_tree_without_policy'));
        return;
      }

      //Identify Duplicates before saving
      const duplicateIDs = this.checkForDuplicates();

      //If duplucate exist, format message for showing duplicate group
      if (duplicateIDs.length > 0) {
        let errorText = this.$t('rows') + ' ';

        duplicateIDs.forEach((dup: any) => {
          errorText += dup.i + '-' + dup.j + ', ';
        });

        errorText = errorText.replace(/, $/, '');
        errorText += ' ' + this.$t('rows_duplicate');
        notify.error(errorText);
        return false;
      }

      try {
        this.showLoading();
        await decisionApiService.updateTable(
          this.record.id,
          this.generateJSON(),
        );
        notify.success('Saved successfully');
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.hideLoading();
      }
    },

    exportTree() {
      const treeName = String(this.record.name);
      const jsonData = this.generateJSON();
      try {
        const blob = new Blob([jsonData], { type: 'application/json' });

        const url = window.URL.createObjectURL(blob);
        const link = document.createElement('a');
        link.href = url;
        link.download = `${treeName}.json`;
        document.body.appendChild(link);
        link.click();

        window.URL.revokeObjectURL(url);
        document.body.removeChild(link);
      } catch (error) {
        logError('Error exporting or downloading file:', error);
      }
    },

    formatFieldName(fieldName: string) {
      return `${this.translatedOrHumanizedFieldName(fieldName)} (${fieldName})`;
    },

    translatedOrHumanizedFieldName(fieldName: string) {
      const translation = this.translateLabel(fieldName);
      if (translation && translation !== fieldName) {
        return translation;
      }
      return this.humanizeFieldName(fieldName);
    },

    humanizeFieldName(fieldName: string) {
      return fieldName
        .split('_')
        .map(
          (word) => word.charAt(0).toUpperCase() + word.slice(1).toLowerCase(),
        )
        .join(' ');
    },

    initData() {
      this.rules.push(this.getEmptyRule());
      this.rules[0].conditions.push(this.getEmptyCondition());
      this.rules[0].output.push(this.getEmptyDecisionResult());
      this.setColumns();
      this.loadOptions();
    },

    setColumns() {
      this.setConditionColumns();
      this.setResultColumns();
    },

    getEmptyRule() {
      return {
        id: 0,
        priority: 0,
        conditions: [],
        output: [],
      };
    },

    setConditionColumns() {
      this.rules_condition_columns = [];
      for (let [key, condition] of Object.entries(this.rules[0].conditions)) {
        const conditionDef = condition as dynamicObj;
        this.rules_condition_columns.push({
          source: conditionDef.source,
          label: this.formatFieldName(conditionDef.field_name),
          value: conditionDef.field_name,
          field_value: conditionDef.field_value,
          isSortingActive: false,
        });
      }
    },

    setResultColumns() {
      this.result_columns = [];
      for (let [key, result] of Object.entries(this.rules[0].output)) {
        const resultDef = result as dynamicObj;
        this.result_columns.push({
          output_type: resultDef.output_type,
          field_name: resultDef.field_name,
        });
      }
    },

    getEmptyCondition() {
      return {
        source: '',
        field_name: '',
        operator: '',
        value: '',
        type: '',
        field_value: '',
      };
    },

    getEmptyDecisionResult() {
      return {
        field_name: '',
        output_type: 'value',
        value: '',
        field_type: '',
      };
    },

    prepareDataForView() {
      try {
        if (isUndefinedOrNull(this.record.data)) {
          this.initData();
          return;
        }
        this.rules = this.record.data;
        this.setColumns();
        this.loadOptions();
      } catch (error) {
        logError('Error loading decision tree data:', error);
        notify.error(error);
      }
    },

    columnSourceUpdated(source: string, index: number) {
      for (let [rule_key, rule] of Object.entries(this.rules)) {
        rule.conditions[index].field_name = '';
        rule.conditions[index].source = source;
        if (source === 'custom_expression') {
          rule.conditions[index].field_name = source;
        } else {
          rule.conditions[index].field_name = '';
        }
      }
    },

    columnValueUpdated(value: string, index: number) {
      for (let [rule_key, rule] of Object.entries(this.rules)) {
        rule.conditions[index].field_value = value;
      }
    },

    conditionColumnUpdated(field_name: string, index: number) {
      if (!this.cst_column_value_types.includes(field_name)) {
        this.getFieldType(field_name);
      }

      for (let [rule_key, rule] of Object.entries(this.rules)) {
        rule.conditions[index].field_name = field_name;
        rule.conditions[index].type = this.field_type_mapping[field_name];
        rule.conditions[index].operator = '';
        rule.conditions[index].field_value = '';
      }
    },

    resultColumnDropdownUpdated(field_name: string, index: number) {
      this.getFieldType(field_name);
      for (let [rule_key, rule] of Object.entries(this.rules)) {
        rule.output[index].field_name = field_name;
        rule.output[index].field_type = this.field_type_mapping[field_name];
      }
    },

    resultColumnUpdated(output_type: string, index: number) {
      for (let [rule_key, rule] of Object.entries(this.rules)) {
        rule.output[index].output_type = output_type;
        rule.output[index].field_name = '';
        rule.output[index].field_type = '';
        rule.output[index].value = '';
      }
    },

    generateJSON() {
      let document_fields = this.doc_field_resp.map((column: any) => {
        return {
          field_name: column.field_name,
          field_type: column.field_type,
          input_type: column.input_type,
        };
      });

      // Reassign IDs to be unique and sequential
      this.rules = this.rules.map((row, index) => ({
        ...row,
        id: index + 1, // or use any unique logic here
      }));

      this.rules.forEach((rule) => {
        rule.output
          .filter((output: any) => output.output_type === 'document_field')
          .forEach((output: any) => {
            const document_field = document_fields.find(
              (field) => field.field_name === output.value,
            );
            if (document_field) {
              output.field_type = document_field.field_type;
              output.input_type = document_field.input_type;
            }
          });
      });

      let decision_tree_for_json = {
        tree_rule: this.record.tree_rule,
        doc_type: this.record.doc_type,
        data: this.rules,
      };

      const jsonString = JSON.stringify(decision_tree_for_json, null, 2);
      return jsonString;
    },

    addNewConditionColumn() {
      for (let [key, rule] of Object.entries(this.rules)) {
        rule.conditions.push(this.getEmptyCondition());
      }
      this.setConditionColumns();
    },

    deleteRuleLine(index: number) {
      this.rules.splice(index, 1);

      // Clear or update highlight IDs if needed
      this.highlightedLineIDs = this.highlightedLineIDs.filter((id) =>
        this.rules.find((r) => r.id === id),
      );

      // Reassign IDs to be unique and sequential
      this.rules = this.rules.map((row, index) => ({
        ...row,
        id: index + 1, // or use any unique logic here
      }));
    },

    addResultColumn() {
      for (let [key, rule] of Object.entries(this.rules)) {
        rule.output.push(this.getEmptyDecisionResult());
      }
      this.setResultColumns();
    },

    getNewRuleConditions() {
      const new_conditions = [];
      for (let [key, condition] of Object.entries(this.rules[0].conditions)) {
        const conditionDef = condition as dynamicObj;
        const newConditionObj = this.getEmptyCondition();
        newConditionObj.field_name = conditionDef.field_name;
        newConditionObj.type = conditionDef.type;
        newConditionObj.field_value = conditionDef.field_value;
        newConditionObj.source = conditionDef.source;
        new_conditions.push(newConditionObj);
      }
      return new_conditions;
    },

    getNewRuleResult() {
      const new_reuslt = [];
      for (let [key, result] of Object.entries(this.rules[0].output)) {
        const resultDef = result as dynamicObj;
        const newResultObj = this.getEmptyDecisionResult();

        newResultObj.field_name = resultDef.field_name;
        newResultObj.output_type = resultDef.output_type;
        newResultObj.field_type = resultDef.field_type;
        new_reuslt.push(newResultObj);
      }
      return new_reuslt;
    },

    AddNewRuleline() {
      let new_rule = this.getEmptyRule() as dynamicObj;
      new_rule.conditions = this.getNewRuleConditions();
      new_rule.output = this.getNewRuleResult();
      // Both tables key their rows by rule id. Saved trees carry ids 1..n,
      // so `rules.length` collides with the last row's id and the duplicate
      // :key lets Vue cross-patch row instances — existing rows can then
      // re-render showing raw user ids instead of names (DOCB-12665).
      // Always assign a fresh id above the current maximum.
      new_rule.id =
        this.rules.reduce(
          (maxId, rule) => Math.max(maxId, Number(rule.id) || 0),
          0,
        ) + 1;
      this.rules.unshift(new_rule);
    },

    deleteConditionColumn(index: number) {
      //Stopping Delete process if only one column is found
      if (this.rules[0].conditions.length == 1) {
        notify.error(this.$t('cannot_delete_one_column'));
        return;
      }
      for (let [key, rule] of Object.entries(this.rules)) {
        rule.conditions.splice(index, 1);
      }
      this.setConditionColumns();
    },

    removeResultColumn(index: number) {
      for (let [key, rule] of Object.entries(this.rules)) {
        rule.output.splice(index, 1);
      }
      this.setResultColumns();
    },

    selectCustomExpression(value: string, index: number, column: any) {
      for (let [rule_key, rule] of Object.entries(this.rules)) {
        rule.conditions[index].field_value += value;
        column.field_value = rule.conditions[index].field_value;
        if (rule.conditions[index].field_value === '[category]') {
          rule.conditions[index].type = 'STRING';
        } else {
          rule.conditions[index].type = 'AMOUNT';
        }
      }
    },

    filterDocTypes(val: string, update: any) {
      if (val === '') {
        update(() => {
          this.filtered_doc_options = this.columnOptions;
        });
      }

      update(() => {
        const filteredOption = val.toLowerCase();
        this.filtered_doc_options = this.columnOptions.filter((option) => {
          return option.label.toLowerCase().includes(filteredOption);
        });
      });
    },

    validatePriority(value: number) {
      if (value < 1 || value > 999) {
        this.isValid = false;
      } else {
        this.isValid = true;
      }
      return this.isValid;
    },

    loadOptions() {
      this.source_options = [
        { label: this.$t('wf_card_Docfield'), value: 'document_field' },
        { label: this.$t('user'), value: 'user' },
        { label: this.$t('custom_expression'), value: 'custom_expression' },
      ];

      this.string_options = [
        { label: this.$t('is'), value: 'is' },
        { label: this.$t('isnot'), value: 'is_not' },
        { label: this.$t('starts_with'), value: 'starts_with' },
        { label: this.$t('ends_with'), value: 'ends_with' },
        { label: this.$t('contains'), value: 'contains' },
        { label: this.$t('not_contains'), value: 'not_contain' },
        { label: this.$t('is_empty'), value: 'is_empty' },
        { label: this.$t('is_not_empty'), value: 'is_not_empty' },
      ];

      this.return_options = [
        { label: this.$t('return_value'), value: 'value' },
        { label: this.$t('set_document_field'), value: 'document_fields' },
        { label: this.$t('return_user'), value: 'user' },
        { label: this.$t('return_group'), value: 'group' },
        { label: this.$t('priority'), value: 'priority' },
        { label: this.$t('return_document_field'), value: 'document_field' },
      ];

      this.rule_options = [
        { label: this.$t('unique'), value: 'unique' },
        { label: this.$t('first'), value: 'first' },
        { label: this.$t('priority'), value: 'priority' },
        { label: this.$t('collect_sum'), value: 'collect_sum' },
        { label: this.$t('collect_min'), value: 'collect_min' },
        { label: this.$t('collect_max'), value: 'collect_max' },
        { label: this.$t('collect_count'), value: 'collect_count' },
        { label: this.$t('rule_order'), value: 'rule_order' },
        { label: this.$t('match_any'), value: 'any' },
        { label: this.$t('first_and_adjacent'), value: 'first & adjacent' },
        { label: this.$t('first_and_next'), value: 'first & next' },
      ];

      this.bool_options = [
        { label: this.$t('is'), value: 'is' },
        { label: this.$t('isnot'), value: 'is_not' },
        { label: this.$t('is_empty'), value: 'is_empty' },
        { label: this.$t('is_not_empty'), value: 'is_not_empty' },
      ];

      this.checkbox_options = [
        { label: this.$t('is_checked'), value: 'is_checked' },
        { label: this.$t('is_not_checked'), value: 'is_not_checked' },
      ];

      this.status_options = [
        { label: this.$t('active'), value: 'active' },
        { label: this.$t('inactive'), value: 'inactive' },
        { label: this.$t('is_empty'), value: 'is_empty' },
        { label: this.$t('is_not_empty'), value: 'is_not_empty' },
      ];

      this.custom_expressions = [
        { label: this.$t('spending'), value: '[spending]' },
        { label: this.$t('quantity_spending'), value: '[qty_spending]' },
        {
          label: this.$t('unit_price_spending'),
          value: '[unit_price_spending]',
        },
        { label: this.$t('category'), value: '[category]' },
        {
          label: this.$t('unit_price_and_charge_spending'),
          value: '[unit_price_and_charge_spending]',
        },
        { label: this.$t('status'), value: '[status]' },
      ];

      this.amount_options = [
        { label: '!=', value: '!=' },
        { label: '=', value: '=' },
        { label: '<', value: '<' },
        { label: '>', value: '>' },
        { label: '>=', value: '>=' },
        { label: '<=', value: '<=' },
        { label: this.$t('is_empty'), value: 'is_empty' },
        { label: this.$t('is_not_empty'), value: 'is_not_empty' },
      ];
    },

    checkForDuplicates() {
      const duplicatesIDs = [];

      for (let i = 0; i < this.rules.length; i++) {
        for (let j = i + 1; j < this.rules.length; j++) {
          //Compare conditions and output of object[i] with object[i+1]
          const currentObj = this.rules[i];
          const nextObj = this.rules[j];

          if (
            JSON.stringify(currentObj.conditions) ===
              JSON.stringify(nextObj.conditions) &&
            JSON.stringify(currentObj.output) === JSON.stringify(nextObj.output)
          ) {
            //If both match, add the current object IDs to duplicates
            duplicatesIDs.push({ i: currentObj.id, j: nextObj.id });
          }
        }
      }
      return duplicatesIDs;
    },

    handleSorting(index: any) {
      //Identify sorting order
      this.sortOrder = this.sortOrder === 'asc' ? 'desc' : 'asc';

      //Track the column to be sorting
      this.rules_condition_columns = this.rules_condition_columns.map(
        (column, rowIndex) => {
          return {
            ...column,
            isSortingActive: rowIndex === index,
          };
        },
      );

      //Perform Sorting
      this.rules.sort((a, b) => {
        const valA = a.conditions[index]?.value ?? 0;
        const valB = b.conditions[index]?.value ?? 0;

        return this.sortOrder === 'asc' ? valA - valB : valB - valA;
      });
    },
    filterColumnOptions(val: string, update: any) {
      if (val === '') {
        update(() => {
          this.columnOptions = this.columnOptionsDup;
        });
      }
      update(() => {
        const filteredOption = val.toLowerCase();
        this.columnOptions = this.columnOptionsDup.filter(
          (option: { label: string }) => {
            return option.label.toLowerCase().includes(filteredOption);
          },
        );
      });
    },
    filterGroup(val: string, update: any) {
      if (val === '') {
        update(() => {
          this.groupOptions = this.groupOptionsDup;
        });
      }
      update(() => {
        console.log(val);
        const filteredOption = val.toLowerCase();
        this.groupOptions = this.groupOptionsDup.filter(
          (option: { label: string }) => {
            return option.label.toLowerCase().includes(filteredOption);
          },
        );
      });
    },
    removeConditionalOptions() {
      //Remove the rule options not needed based on doc_type
      const matchedValues = this.rules_options_filter.find(
        (r) => r.type === this.record.doc_type,
      );

      const valuesToRemove = matchedValues ? matchedValues.values : [];

      this.rule_options = this.rule_options.filter(
        (options) => !valuesToRemove.includes(options.value),
      );

      //Remove Source Type  for supplier
      if (this.record.doc_type == 'SUPPLIER_M3') {
        this.source_options = this.source_options.filter(
          (options) => !['custom_expression'].includes(options.value),
        );
      }
    },

    setupScrollSync() {
      // Find the actual scrollable elements within the q-markup-table
      const conditionWrapper = this.$refs.conditionTableWrapper as HTMLElement;
      const resultWrapper = this.$refs.resultTableWrapper as HTMLElement;
      if (conditionWrapper && resultWrapper) {
        // Find the scrollable container - could be the wrapper itself or a child
        this.conditionScrollEl =
          conditionWrapper.querySelector('.q-table__container') ||
          conditionWrapper.querySelector('.q-table') ||
          conditionWrapper;
        this.resultScrollEl =
          resultWrapper.querySelector('.q-table__container') ||
          resultWrapper.querySelector('.q-table') ||
          resultWrapper;
        // Attach scroll listeners to the actual scrollable elements
        if (this.conditionScrollEl) {
          this.conditionScrollEl.addEventListener(
            'scroll',
            this.onConditionScroll,
          );
        }
        if (this.resultScrollEl) {
          this.resultScrollEl.addEventListener('scroll', this.onResultScroll);
        }
      }
    },
    onConditionScroll(event: Event) {
      if (this.isScrollSyncing) return;
      if (this.conditionScrollEl && this.resultScrollEl) {
        this.isScrollSyncing = true;
        this.resultScrollEl.scrollTop = this.conditionScrollEl.scrollTop;
        // Use requestAnimationFrame to reset flag after scroll completes
        requestAnimationFrame(() => {
          this.isScrollSyncing = false;
        });
      }
    },
    onResultScroll(event: Event) {
      if (this.isScrollSyncing) return;
      if (this.conditionScrollEl && this.resultScrollEl) {
        this.isScrollSyncing = true;
        this.conditionScrollEl.scrollTop = this.resultScrollEl.scrollTop;
        // Use requestAnimationFrame to reset flag after scroll completes
        requestAnimationFrame(() => {
          this.isScrollSyncing = false;
        });
      }
    },
  },
  data() {
    return {
      searchTerm: '',
      sortOrder: 'asc',
      rules_options_filter,
      isScrollSyncing: false,
      conditionScrollEl: null as HTMLElement | null,
      resultScrollEl: null as HTMLElement | null,
    };
  },
  computed: {
    filteredExpressions() {
      const term = this.searchTerm.toLowerCase();
      return this.custom_expressions.filter((expr) =>
        expr.label.toLowerCase().includes(term),
      );
    },
  },

  setup() {
    return {
      doc_field_resp: [],
      highlightedLineIDs: ref([] as number[]),
      highlightedLineID: null,
      first_rule_fields: ref([]),
      testDialog: ref(false),
      data: ref([] as dynamicObj[]),
      rules: ref([] as dynamicObj[]),
      rules_condition_columns: ref([] as dynamicObj[]),
      result_columns: ref([] as dynamicObj[]),
      columnOptions: ref<Array<{ label: string; value: string; type: string }>>(
        [
          { label: '', value: '', type: '' },
          { label: '', value: '', type: '' },
        ],
      ),
      userOptions: ref<Array<{ label: string; value: string }>>([
        { label: '', value: '' },
        { label: '', value: '' },
      ]),
      groupOptions: ref<Array<{ label: string; value: string }>>([
        { label: '', value: '' },
        { label: '', value: '' },
      ]),
      empty_options: ref([]),
      field_type_mapping: ref({} as dynamicObj),
      record: ref({} as dynamicObj),
      completeDataSet: ref({} as dynamicObj),
      currentPage: ref(1),
      decisionTreeName: ref(''),
      splitter: ref(50),
      cst_column_value_types: ['custom_expression'],
      filtered_doc_options: ref<
        Array<{ label: string; value: string; type: string }>
      >([
        { label: '', value: '', type: '' },
        { label: '', value: '', type: '' },
      ]),
      doc_fields: ref<Array<{ name: string; value: string }>>([]),
      isValid: ref(true),
      source_options: ref<Array<{ label: string; value: string }>>([
        { label: '', value: '' },
      ]),
      string_options: ref<Array<{ label: string; value: string }>>([
        { label: '', value: '' },
      ]),
      return_options: ref<Array<{ label: string; value: string }>>([
        { label: '', value: '' },
      ]),
      rule_options: ref<Array<{ label: string; value: string }>>([
        { label: '', value: '' },
      ]),
      bool_options: ref<Array<{ label: string; value: string }>>([
        { label: '', value: '' },
      ]),
      checkbox_options: ref<Array<{ label: string; value: string }>>([
        { label: '', value: '' },
      ]),
      status_options: ref<Array<{ label: string; value: string }>>([
        { label: '', value: '' },
      ]),
      custom_expressions: ref<Array<{ label: string; value: string }>>([
        { label: '', value: '' },
      ]),
      amount_options: ref<Array<{ label: string; value: string }>>([
        { label: '', value: '' },
      ]),
      testResultDialog: ref(false),
      testResults: ref({}),
      columnOptionsDup: [] as any,
      groupOptionsDup: [] as any,
    };
  },
});
</script>

